// ============================================================================
// LOG PARSING PATTERNS
// ============================================================================
export const LOG_PATTERNS = [
  { name: "Apache Combined Log", pattern: "^(\\S+) (\\S+) (\\S+) \\[([^\\]]+)\\] \"(\\S+) (\\S+) (\\S+)\" (\\d{3}) (\\d+|-) \"([^\"]*)\" \"([^\"]*)\"", flags: "m", description: "Apache combined log format: IP, ident, user, timestamp, method, path, protocol, status, size, referrer, user-agent", test_strings: [{ input: "192.168.1.1 - admin [08/Sep/2026:14:00:00 +0000] \"GET /index.html HTTP/1.1\" 200 1234 \"-\" \"Mozilla/5.0\"", matches: ["192.168.1.1", "-", "admin", "08/Sep/2026:14:00:00 +0000", "GET", "/index.html", "HTTP/1.1", "200", "1234", "-", "Mozilla/5.0"] }], use_case: "Web log analysis", language_notes: "Use named groups in production" },
  { name: "Apache Error Log", pattern: "^\\[(\\w+ \\w+ \\d+ [\\d:]+\\.\\d+ \\d+)\\] \\[(\\S+):(\\w+)\\] \\[pid (\\d+)(?::tid (\\d+))?\\](?: \\[client ([^\\]]+)\\])? (.+)", flags: "m", description: "Apache error log format", test_strings: [], use_case: "Error analysis", language_notes: "Format varies by version" },
  { name: "Nginx Access Log", pattern: "^(\\S+) - (\\S+) \\[([^\\]]+)\\] \"(\\S+) (\\S+) (\\S+)\" (\\d{3}) (\\d+) \"([^\"]*)\" \"([^\"]*)\"", flags: "m", description: "Default nginx access log format", test_strings: [], use_case: "Web log analysis", language_notes: "Same as Apache combined by default" },
  { name: "Syslog (RFC 3164)", pattern: "^<(\\d+)>(\\w{3}\\s+\\d{1,2}\\s+[\\d:]+) (\\S+) (\\S+?)(?:\\[(\\d+)\\])?: (.+)", flags: "m", description: "Traditional BSD syslog format: priority, timestamp, host, process, PID, message", test_strings: [{ input: "<34>Sep  8 14:30:00 server sshd[12345]: Failed password for root from 10.0.0.1 port 22", matches: ["34", "Sep  8 14:30:00", "server", "sshd", "12345"] }], use_case: "System log parsing", language_notes: "Universal" },
  { name: "Syslog (RFC 5424)", pattern: "^<(\\d+)>(\\d+) (\\S+) (\\S+) (\\S+) (\\S+) (\\S+) (?:\\[([^\\]]+)\\])? (.+)", flags: "m", description: "Structured syslog: priority, version, timestamp, hostname, app, procid, msgid, structured-data, message", test_strings: [], use_case: "Modern syslog analysis", language_notes: "Universal" },
  { name: "auth.log — Failed login", pattern: "Failed (?:password|publickey) for (?:invalid user )?(\\S+) from (\\S+) port (\\d+)", flags: "g", description: "SSH failed authentication", test_strings: [{ input: "Failed password for root from 10.0.0.1 port 22 ssh2", matches: ["root", "10.0.0.1", "22"] }], use_case: "Brute force detection", language_notes: "Linux" },
  { name: "auth.log — Successful login", pattern: "Accepted (?:password|publickey) for (\\S+) from (\\S+) port (\\d+)", flags: "g", description: "SSH successful authentication", test_strings: [{ input: "Accepted password for admin from 192.168.1.1 port 22 ssh2", matches: ["admin", "192.168.1.1", "22"] }], use_case: "Login tracking", language_notes: "Linux" },
  { name: "auth.log — sudo", pattern: "(\\S+) : TTY=(\\S+) ; PWD=(\\S+) ; USER=(\\S+) ; COMMAND=(.+)", flags: "g", description: "sudo command execution", test_strings: [{ input: "admin : TTY=pts/0 ; PWD=/home/admin ; USER=root ; COMMAND=/bin/cat /etc/shadow", matches: ["admin", "pts/0", "/home/admin", "root", "/bin/cat /etc/shadow"] }], use_case: "Privilege escalation tracking", language_notes: "Linux" },
  { name: "Windows Event — Logon (4624)", pattern: "An account was successfully logged on.*?Account Name:\\s+(\\S+).*?Source Network Address:\\s+(\\S+)", flags: "gs", description: "Windows Security Event 4624 — successful logon", test_strings: [], use_case: "Windows login tracking", language_notes: "Windows Event Log" },
  { name: "Windows Event — Failed Logon (4625)", pattern: "An account failed to log on.*?Account Name:\\s+(\\S+).*?Source Network Address:\\s+(\\S+).*?Failure Reason:\\s+(.+?)\\s*$", flags: "gsm", description: "Windows Security Event 4625 — failed logon", test_strings: [], use_case: "Windows brute force detection", language_notes: "Windows Event Log" },
  { name: "Windows Event — Process (4688)", pattern: "A new process has been created.*?New Process Name:\\s+(.+?)\\s*(?:Creator )?Process Name:\\s+(.+?)\\s*Command ?Line:\\s+(.+?)\\s*$", flags: "gsm", description: "Windows Event 4688 — process creation", test_strings: [], use_case: "Process execution tracking", language_notes: "Windows — enable command line auditing" },
  { name: "iptables Log", pattern: "(?:IN=(\\S*) OUT=(\\S*)|SRC=(\\S+) DST=(\\S+)|PROTO=(\\S+)|SPT=(\\d+) DPT=(\\d+))", flags: "g", description: "Linux iptables/netfilter log fields", test_strings: [{ input: "IN=eth0 OUT= SRC=10.0.0.1 DST=192.168.1.1 PROTO=TCP SPT=54321 DPT=22", matches: ["IN=eth0 OUT=", "SRC=10.0.0.1 DST=192.168.1.1", "PROTO=TCP", "SPT=54321 DPT=22"] }], use_case: "Firewall log analysis", language_notes: "Linux" },
  { name: "DNS Query Log", pattern: "query\\[([A-Z]+)\\]\\s+(\\S+)\\s+from\\s+(\\S+)", flags: "g", description: "DNS server query log (BIND/dnsmasq style)", test_strings: [{ input: "query[A] evil.com from 10.0.0.50", matches: ["A", "evil.com", "10.0.0.50"] }], use_case: "DNS monitoring, C2 detection", language_notes: "BIND/dnsmasq" },
  { name: "Postfix SMTP Log", pattern: "(?:from=<([^>]*)>|to=<([^>]*)>|status=(\\S+))", flags: "g", description: "Postfix mail transfer agent log", test_strings: [{ input: "from=<sender@example.com>, to=<recipient@target.com>, status=sent", matches: ["sender@example.com", "recipient@target.com", "sent"] }], use_case: "Email flow analysis", language_notes: "Postfix" },
  { name: "JSON Log Line", pattern: "^\\{\"(?:timestamp|time|@timestamp|ts)\"\\s*:\\s*\"([^\"]+)\"", flags: "m", description: "JSON-structured log entry timestamp extraction", test_strings: [{ input: "{\"timestamp\":\"2026-09-08T14:30:00Z\",\"level\":\"error\"}", matches: ["2026-09-08T14:30:00Z"] }], use_case: "Structured log parsing", language_notes: "Universal" },
  { name: "Fail2ban Action", pattern: "(?:Ban|Unban|Found)\\s+(\\S+)", flags: "g", description: "Fail2ban ban/unban/found actions", test_strings: [{ input: "Ban 10.0.0.50", matches: ["10.0.0.50"] }], use_case: "Intrusion prevention monitoring", language_notes: "Linux" },
];

