// ============================================================================
// PROGRAMMING PATTERNS
// ============================================================================
export const PROGRAMMING_PATTERNS = [
  { name: "Python — import", pattern: "^(?:from\\s+(\\S+)\\s+)?import\\s+(.+)", flags: "gm", description: "Python import statement", test_strings: [{ input: "from os import path", matches: ["os", "path"] }], use_case: "Dependency analysis", language_notes: "Python" },
  { name: "Python — def function", pattern: "^\\s*def\\s+(\\w+)\\s*\\(([^)]*)\\)\\s*(?:->\\s*(\\S+))?\\s*:", flags: "gm", description: "Python function definition", test_strings: [{ input: "def process_data(items: list) -> dict:", matches: ["process_data", "items: list", "dict"] }], use_case: "Code analysis, documentation", language_notes: "Python" },
  { name: "Python — class", pattern: "^\\s*class\\s+(\\w+)(?:\\(([^)]*)\\))?\\s*:", flags: "gm", description: "Python class definition", test_strings: [{ input: "class MyClass(BaseModel):", matches: ["MyClass", "BaseModel"] }], use_case: "Code structure analysis", language_notes: "Python" },
  { name: "JavaScript — import", pattern: "import\\s+(?:\\{([^}]+)\\}|([\\w$]+))\\s+from\\s+['\"]([^'\"]+)['\"]", flags: "gm", description: "ES6 import statement", test_strings: [{ input: "import { useState } from 'react'", matches: ["useState", "react"] }], use_case: "Dependency analysis", language_notes: "JS/TS" },
  { name: "JavaScript — require", pattern: "(?:const|let|var)\\s+(\\{[^}]+\\}|\\w+)\\s*=\\s*require\\(['\"]([^'\"]+)['\"]\\)", flags: "gm", description: "CommonJS require", test_strings: [{ input: "const fs = require('fs')", matches: ["fs", "fs"] }], use_case: "Node.js dependency analysis", language_notes: "Node.js" },
  { name: "JavaScript — function", pattern: "(?:function\\s+(\\w+)|(?:const|let|var)\\s+(\\w+)\\s*=\\s*(?:async\\s+)?(?:function|\\([^)]*\\)\\s*=>))", flags: "gm", description: "JS function (declaration, expression, arrow)", test_strings: [{ input: "const processData = async (items) => {", matches: ["processData"] }], use_case: "Code analysis", language_notes: "JS/TS" },
  { name: "Java — import", pattern: "^import\\s+(?:static\\s+)?([\\w.]+(?:\\.\\*)?);", flags: "gm", description: "Java import statement", test_strings: [{ input: "import java.util.ArrayList;", matches: ["java.util.ArrayList"] }], use_case: "Dependency analysis", language_notes: "Java" },
  { name: "Java — class/interface", pattern: "(?:public|private|protected)?\\s*(?:abstract|final)?\\s*(?:class|interface|enum)\\s+(\\w+)(?:\\s+extends\\s+(\\w+))?(?:\\s+implements\\s+([\\w,\\s]+))?", flags: "gm", description: "Java class/interface/enum definition", test_strings: [{ input: "public class UserService extends BaseService implements Serializable {", matches: ["UserService", "BaseService", "Serializable"] }], use_case: "Code structure analysis", language_notes: "Java" },
  { name: "Go — import", pattern: "import\\s+(?:\"([^\"]+)\"|\\(([^)]+)\\))", flags: "gm", description: "Go import (single or block)", test_strings: [{ input: "import \"fmt\"", matches: ["fmt"] }], use_case: "Dependency analysis", language_notes: "Go" },
  { name: "Go — func", pattern: "func\\s+(?:\\(\\w+\\s+\\*?(\\w+)\\)\\s+)?(\\w+)\\s*\\(([^)]*)\\)(?:\\s*(?:\\(([^)]*)\\)|(\\S+)))?", flags: "gm", description: "Go function/method definition", test_strings: [{ input: "func (s *Server) handleRequest(w http.ResponseWriter, r *http.Request) error {", matches: ["Server", "handleRequest"] }], use_case: "Code analysis", language_notes: "Go" },
  { name: "Rust — use", pattern: "^use\\s+([\\w:]+(?:::\\{[^}]+\\}|::\\*)?);", flags: "gm", description: "Rust use/import statement", test_strings: [{ input: "use std::collections::HashMap;", matches: ["std::collections::HashMap"] }], use_case: "Dependency analysis", language_notes: "Rust" },
  { name: "Rust — fn", pattern: "(?:pub\\s+)?(?:async\\s+)?fn\\s+(\\w+)(?:<[^>]+>)?\\s*\\(([^)]*)\\)(?:\\s*->\\s*(.+?))?\\s*(?:\\{|where)", flags: "gm", description: "Rust function definition", test_strings: [{ input: "pub async fn process(data: &[u8]) -> Result<Vec<u8>, Error> {", matches: ["process"] }], use_case: "Code analysis", language_notes: "Rust" },
  { name: "C/C++ — #include", pattern: "#include\\s+[<\"]([^>\"]+)[>\"]", flags: "gm", description: "C/C++ include directive", test_strings: [{ input: "#include <stdio.h>", matches: ["stdio.h"] }], use_case: "Dependency analysis", language_notes: "C/C++" },
  { name: "TODO/FIXME/HACK comment", pattern: "(?://|#|/\\*|--|;;)\\s*(?:TODO|FIXME|HACK|BUG|XXX|OPTIMIZE|NOTE|WARNING|DEPRECATED)\\b[:\\s]*(.*?)(?:\\*/)?$", flags: "gim", description: "Code annotation markers", test_strings: [{ input: "// TODO: fix race condition in auth handler", matches: ["fix race condition in auth handler"] }], use_case: "Technical debt tracking", language_notes: "Multi-language" },
  { name: "Single-line comment", pattern: "(?://|#)\\s*(.+)$", flags: "gm", description: "Single-line comment (C-style or hash)", test_strings: [{ input: "// This handles authentication", matches: ["This handles authentication"] }], use_case: "Documentation extraction", language_notes: "Multi-language" },
  { name: "SQL Query", pattern: "(?:SELECT|INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|GRANT|REVOKE|TRUNCATE)\\s+[\\s\\S]+?(?:;|$)", flags: "gim", description: "SQL statement extraction", test_strings: [{ input: "SELECT * FROM users WHERE id = 1;", matches: ["SELECT * FROM users WHERE id = 1;"] }], use_case: "SQL extraction from logs/code", language_notes: "Universal SQL" },
];

// ============================================================================
// NETWORK PATTERNS
// ============================================================================
export const NETWORK_PATTERNS = [
  { name: "HTTP Request Line", pattern: "(GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS|TRACE|CONNECT)\\s+(\\S+)\\s+HTTP/(\\d\\.\\d)", flags: "gm", description: "HTTP request method, URI, and version", test_strings: [{ input: "GET /api/users?page=1 HTTP/1.1", matches: ["GET", "/api/users?page=1", "1.1"] }], use_case: "HTTP log parsing", language_notes: "Universal" },
  { name: "HTTP Status Line", pattern: "HTTP/(\\d\\.\\d)\\s+(\\d{3})\\s+(.+?)$", flags: "gm", description: "HTTP response status line", test_strings: [{ input: "HTTP/1.1 200 OK", matches: ["1.1", "200", "OK"] }], use_case: "Response parsing", language_notes: "Universal" },
  { name: "HTTP Header", pattern: "^([A-Za-z][A-Za-z0-9-]*):\\s*(.+?)\\s*$", flags: "gm", description: "HTTP header name: value pair", test_strings: [{ input: "Content-Type: application/json; charset=utf-8", matches: ["Content-Type", "application/json; charset=utf-8"] }], use_case: "Header extraction", language_notes: "Universal" },
  { name: "Cookie Header", pattern: "Cookie:\\s*(.+?)$", flags: "gm", description: "Cookie header value extraction", test_strings: [{ input: "Cookie: session=abc123; user=admin", matches: ["session=abc123; user=admin"] }], use_case: "Session analysis", language_notes: "Universal" },
  { name: "Set-Cookie Header", pattern: "Set-Cookie:\\s*(\\S+?)=([^;]*);?\\s*(.*?)$", flags: "gm", description: "Set-Cookie with name, value, attributes", test_strings: [{ input: "Set-Cookie: session=abc123; Path=/; HttpOnly; Secure; SameSite=Strict", matches: ["session", "abc123", "Path=/; HttpOnly; Secure; SameSite=Strict"] }], use_case: "Cookie security analysis", language_notes: "Universal" },
  { name: "User-Agent String", pattern: "User-Agent:\\s*(.+?)$", flags: "gm", description: "User-Agent header extraction", test_strings: [{ input: "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36", matches: ["Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"] }], use_case: "Client fingerprinting, bot detection", language_notes: "Universal" },
  { name: "Authorization Bearer", pattern: "Authorization:\\s*Bearer\\s+(\\S+)", flags: "gm", description: "Bearer token from Authorization header", test_strings: [{ input: "Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyIjoiYWRtaW4ifQ.sig", matches: ["eyJhbGciOiJIUzI1NiJ9.eyJ1c2VyIjoiYWRtaW4ifQ.sig"] }], use_case: "Token extraction", language_notes: "Universal" },
  { name: "Authorization Basic", pattern: "Authorization:\\s*Basic\\s+([A-Za-z0-9+/=]+)", flags: "gm", description: "Basic auth credentials (base64 encoded)", test_strings: [{ input: "Authorization: Basic YWRtaW46cGFzc3dvcmQ=", matches: ["YWRtaW46cGFzc3dvcmQ="] }], use_case: "Credential extraction (decode base64)", language_notes: "Universal" },
  { name: "Referer Header", pattern: "Referer:\\s*(\\S+)", flags: "gm", description: "HTTP Referer header value", test_strings: [{ input: "Referer: https://example.com/login", matches: ["https://example.com/login"] }], use_case: "CSRF analysis, navigation tracking", language_notes: "Note: misspelling is intentional per RFC" },
  { name: "X-Forwarded-For", pattern: "X-Forwarded-For:\\s*([\\d., ]+)", flags: "gm", description: "Client IP chain from reverse proxy", test_strings: [{ input: "X-Forwarded-For: 203.0.113.50, 70.41.3.18", matches: ["203.0.113.50, 70.41.3.18"] }], use_case: "True client IP extraction, IP spoofing detection", language_notes: "Universal" },
];

// ============================================================================
// FILE CONTENT PATTERNS
// ============================================================================
export const FILE_PATTERNS = [
  { name: "Shebang (hashbang)", pattern: "^#!\\s*(/\\S+)", flags: "m", description: "Script interpreter directive", test_strings: [{ input: "#!/usr/bin/env python3", matches: ["/usr/bin/env"] }], use_case: "Script type identification", language_notes: "Unix" },
  { name: "PEM Certificate", pattern: "-----BEGIN CERTIFICATE-----[\\s\\S]+?-----END CERTIFICATE-----", flags: "g", description: "PEM-encoded X.509 certificate", test_strings: [], use_case: "Certificate extraction from configs", language_notes: "Universal" },
  { name: "PEM Private Key", pattern: "-----BEGIN (?:RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----[\\s\\S]+?-----END (?:RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----", flags: "g", description: "PEM-encoded private key", test_strings: [], use_case: "Private key leak detection", language_notes: "Critical finding" },
  { name: "PGP Public Key Block", pattern: "-----BEGIN PGP PUBLIC KEY BLOCK-----[\\s\\S]+?-----END PGP PUBLIC KEY BLOCK-----", flags: "g", description: "PGP/GPG public key", test_strings: [], use_case: "Key extraction", language_notes: "Universal" },
  { name: "SSH Public Key", pattern: "ssh-(?:rsa|ed25519|ecdsa|dss)\\s+[A-Za-z0-9+/=]+(?:\\s+\\S+)?", flags: "g", description: "OpenSSH public key", test_strings: [{ input: "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAAB... user@host", matches: ["ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAAB... user@host"] }], use_case: "SSH key management", language_notes: "Universal" },
  { name: "INI Config Key", pattern: "^(\\w[\\w.-]*)\\s*=\\s*(.+?)\\s*$", flags: "gm", description: "INI/properties file key=value", test_strings: [{ input: "database.host = 10.0.0.5", matches: ["database.host", "10.0.0.5"] }], use_case: "Config file parsing", language_notes: "Universal" },
  { name: "INI Section Header", pattern: "^\\[([^\\]]+)\\]", flags: "gm", description: "INI file section header", test_strings: [{ input: "[database]", matches: ["database"] }], use_case: "Config structure analysis", language_notes: "Universal" },
  { name: "YAML Key-Value", pattern: "^(\\s*)(\\w[\\w.-]*)\\s*:\\s*(.+?)\\s*$", flags: "gm", description: "YAML key: value pair", test_strings: [{ input: "  host: localhost", matches: ["  ", "host", "localhost"] }], use_case: "YAML config parsing", language_notes: "Universal" },
  { name: "Docker ENV/ARG", pattern: "^(?:ENV|ARG)\\s+(\\w+)(?:[= ](.+))?$", flags: "gm", description: "Dockerfile ENV or ARG directive", test_strings: [{ input: "ENV DATABASE_URL=postgres://user:pass@db:5432/app", matches: ["DATABASE_URL", "postgres://user:pass@db:5432/app"] }], use_case: "Secret in Dockerfile detection", language_notes: "Docker" },
  { name: "Connection String", pattern: "(?:postgres|mysql|mongodb|redis|amqp|mssql)://(?:[^:]+):([^@]+)@[^/]+/\\S+", flags: "gi", description: "Database connection string with embedded credentials", test_strings: [{ input: "postgres://admin:s3cr3t@db.example.com:5432/production", matches: ["s3cr3t"] }], use_case: "Credential leak detection", language_notes: "Universal" },
  { name: "AWS ARN", pattern: "arn:aws(?:-[a-z]+)?:[a-z0-9-]+:[a-z0-9-]*:\\d{12}:[\\w+=,.@/-]+", flags: "g", description: "Amazon Resource Name", test_strings: [{ input: "arn:aws:iam::123456789012:role/MyRole", matches: ["arn:aws:iam::123456789012:role/MyRole"] }], use_case: "AWS resource identification", language_notes: "AWS" },
  { name: "File magic — PDF", pattern: "^%PDF-", flags: "m", description: "PDF file signature", test_strings: [{ input: "%PDF-1.7", matches: ["%PDF-"] }], use_case: "File type identification", language_notes: "Universal" },
  { name: "File magic — ZIP/DOCX/XLSX/JAR", pattern: "^PK\\x03\\x04", flags: "m", description: "ZIP archive (also DOCX, XLSX, JAR, APK)", test_strings: [], use_case: "File type identification", language_notes: "Binary — use hex match" },
  { name: "File magic — ELF binary", pattern: "^\\x7fELF", flags: "m", description: "Linux ELF executable/shared library", test_strings: [], use_case: "Binary detection", language_notes: "Linux" },
  { name: "File magic — PE/MZ", pattern: "^MZ", flags: "m", description: "Windows PE executable (MZ header)", test_strings: [], use_case: "Windows executable detection", language_notes: "Windows" },
];

